// The behaviour corpus, rebuilt from a recorded probe: thirty commands an agent writes or
// that probe a shell's edges (pipes, `cd &&`, heredocs, `set -e`, subshells, background jobs, `exec`, `trap`, syntax errors, env dumps),
// plus Python and Node children that write files, so the write hooks run inside the comparison. Each runs in a fresh scratch folder.
// Every command is deterministic (no pids, clocks or random paths in its output).
export const CORPUS: readonly string[] = [
  "echo hello",
  "printf 'a\\nb\\nc\\n' | sort -r | head -2",
  "mkdir -p sub && cd sub && pwd -P | sed 's#.*/##'",
  "cd sub 2>/dev/null || echo 'no sub'",
  "set -e; false; echo 'not reached'",
  "set -e\necho one\nfalse\necho two",
  "(cd /; pwd); pwd -P | sed 's#.*/##'",
  "cat <<EOF\nline one\nline two\nEOF",
  "cat <<'EOF' > here.txt\n$HOME stays literal\nEOF\ncat here.txt",
  "sleep 0.1 & wait; echo waited",
  "exec echo replaced",
  "trap 'echo trapped' EXIT; echo body",
  "exit 3",
  "false || echo recovered; true && echo chained",
  "echo \"unterminated",
  "if true; then echo",
  "for i in 1 2 3; do echo n$i; done | tr '\\n' ' '",
  "x=5; echo $((x * 2))",
  "echo $0 | sed 's#.*/##'",
  "ls nonexistent-file",
  "env | grep -c COCHECK_CALL || true",
  "printenv COCHECK_CALL || echo absent",
  "env | grep -i cocheck-call | wc -l",
  "python3 -c \"import os; print(sorted(k for k in os.environ if k.startswith('COCHECK_CALL')))\"",
  "node -e \"console.log(Object.keys(process.env).filter(k => k.startsWith('COCHECK_CALL')))\"",
  "python3 -c \"open('py.txt','w').write('py'); print(open('py.txt').read())\"",
  "node -e \"require('fs').writeFileSync('n.txt','node'); console.log(require('fs').readFileSync('n.txt','utf8'))\"",
  "python3 -c \"import sys; sys.exit(4)\"; echo code=$?",
  "node -e \"process.stderr.write('to stderr\\n'); process.exit(5)\"",
  "echo first; echo second >&2; echo third",
];
